import logging
from taf.collectors.core import CollectorKeywords
from .logcollection import LogCollection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class log_collection(CollectorKeywords):
    """
    Unified log collection.

    Collect groups of logs independent of testline topology.
    """
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def __init__(self, tl_config=None, **kwargs):
        super(log_collection, self).__init__(**kwargs)
        if tl_config is None:
            tl_config = self._builtin.get_variable_value("${tl}")
        self.log_collection = LogCollection(tl_config=tl_config)

    def create_collectors_using_testline_information(self, names, configuration, network_elements=None):
        """
        Create collector configurations using tl config.

        It generates from an abstract log configuration the collector configuration for
        taf.collectors.core. Any additional needed configuration is taken from
        the taf.config.testline structure or fetched from the BTS respective
        real testline itself.

        :param str names: comma separated list of the names of the collectors to be created (subset of toplevel names in
                          "configuration").
        :param list network_elements: (optional) network elements to collect logs from. Example: "gnb_0"
                                      or "gnb_0,gnb_1,enb_0", default: all network elements in tl config
        :param dict configuration: Defines the collectors, their types and if needed their additional configurations.

        Please note: As of now supported logs types are 'bip', 'emil', 'ocp',
        'pmcounters', 'protocols', 'snapshot', 'syslog', 'uplane_trace'.

        Please see :ref:`example page<example>` for working examples of each log type.

        Here is a possible example for this configuration structure:

        .. code:: json

            {"RealTimeLogs": {"type": "group",
                              "members": "TTI_Trace, BIP_Trace"},
             "TTI_Trace":    {"type": "uplane_trace",
                              "components": "l2ps"},
             "BIP_Trace":    {"type": "bip"},
             "LongTimeLogs": {"type": "group",
                              "members": "TestSyslog"},
             "TestSyslog":   {"type": "syslog"}}

        This data structure can be constructed with help of the robotframework keywords "Create Dictionary" for each and every sub-dictionary.
        Another possibility would be by using the keyword "Evaluate" using the python way of describing a more complex dictionary.

        In this configuration three trace types are defined, tti, bip and syslog. Since the bip trace and tti trace are collecting a lot of data,
        they are grouped within a collector group called “RealTimeLogs”. The syslog is not that time critical, so it is put in a separate group
        “LongTimeLogs”.

        Here is a possible usage example for this configuration structure:

        .. code:: robotframework

            *** Settings ***
            Library    taf.ul.log_collection

            *** Test Cases ***
            Collect the Syslog

                ${log_config_string}=   Catenate       {"RealTimeLogs": {"type": "group",
                ...                                                      "members": "TTI_Trace, BIP_Trace"},
                ...                                     "TTI_Trace":    {"type": "uplane_trace",
                ...                                                      "components": "l2ps"},
                ...                                     "BIP_Trace":    {"type": "bip"},
                ...                                     "LongTimeLogs": {"type": "group",
                ...                                                      "members": "TestSyslog"},
                ...                                     "TestSyslog":   {"type": "syslog"}}

                ${log_configuration}=    Evaluate   ${log_config_string}

                Create Collectors Using Testline Information   names=RealTimeLogs,LongTimeLogs
                ...                                            network_elements=gnb_0
                ...                                            configuration=${log_configuration}

                Setup Collectors    names=LongTimeLogs
                Start Collectors    names=LongTimeLogs

                # here normally some preparation steps might be done to i.e.
                # - enable the feature/several settings by delta-commissioning
                # - taf.ul.hangin_resources: get current used resources
                # - remember <timestamp>

                Setup Collectors    names=RealTimeLogs
                Start Collectors    names=RealTimeLogs

                # Here the test action is happening, i.e.
                # - attach ue(s)
                # - do call processing, traffic, handover, ...
                Sleep    5s

                Stop Collectors      names=RealTimeLogs
                Collect Collectors   names=RealTimeLogs    target_dir=/tmp
                Teardown Collectors  names=RealTimeLogs

                # here might be some postwork, before also the long running logs are collected,
                # things like:
                # - delta-commissioning of BTS to disable feature again
                # - check for hanging resources
                # - check syslog for errors since <timestamp>

                Stop Collectors      names=LongTimeLogs
                Collect Collectors   names=LongTimeLogs    target_dir=/tmp
                Teardown Collectors  names=LongTimeLogs

                ${log_file}=    Get Log File

        """
        collectors = self.log_collection.create_collectors_using_testline_information(
            names=names,
            configuration=configuration,
            network_elements=network_elements,
            available_collectors=self._get_all_alias_from_collector_namespace())
        for name, collector in collectors.items():
            self.set_alias(name, collector)
            logger.info("Collector %r with type %s created", name, collector.__class__.__name__)

    def get_log_file(self, log_type, network_element, target_dir):
        """
        Provide the path to the log file

        :param str log_type: The type of the log to get the file for. Refer
                             :meth:`create_collectors_using_testline_information`
                             for supported log types in detail.
        :param str network_element: The network element the log was collected on, i.e. gnb_0
        :param str target_dir: The target directory which was used during collection

        """
        return self.log_collection.get_log_file(log_type=log_type,
                                                network_element=network_element,
                                                target_dir=target_dir)
